<section class="ac-card"><div class="ac-head"><div><h2>Customer directory</h2><p>Live customer records. Contact details stay masked until an authorized purpose is recorded.</p></div><div class="ac-toolbar"><input class="ac-input" id="ac-customer-search" type="search" placeholder="Search customer or email"><select class="ac-select" id="ac-customer-filter"><option value="">All statuses</option><option value="active">Active</option><option value="restricted">Restricted</option><option value="blocked">Blocked</option></select><button class="ac-btn" id="ac-customer-refresh" type="button">Refresh</button></div></div><div class="ac-body"><p id="ac-customer-status" role="status">Loading customers…</p><div class="ac-table-wrap"><table class="ac-table"><thead><tr><th>Customer</th><th>Account</th><th>Orders</th><th>Lifetime value</th><th>Joined</th><th>Action</th></tr></thead><tbody id="ac-customer-rows"></tbody></table></div></div></section>
<section class="ac-card mt-3" id="ac-customer-detail" hidden><div class="ac-head"><h2>Authorized customer review</h2><button class="ac-btn" id="ac-customer-hide" type="button">Close</button></div><div class="ac-body"><p id="ac-customer-identity"></p><div class="ac-field"><label>Reason for account action<textarea class="ac-textarea" id="ac-customer-reason" minlength="10" maxlength="1000" placeholder="Describe specific evidence and policy basis."></textarea></label></div><div class="ac-actions mt-3"><button class="ac-btn" type="button" data-customer-status="active">Restore active</button><button class="ac-btn" type="button" data-customer-status="restricted">Restrict</button><button class="ac-btn danger" type="button" data-customer-status="blocked">Block</button></div><p class="mt-2">Repeated-return flags require human review; they never change account status automatically. <a href="returns.php">Review return flags</a></p></div></section>
